head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.vScrenID = "ULDSTF05403.xml";
scwin.vScrenTpCD = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.vSecugrpID;
scwin.mktTpCd; //거래시장구분 1= 유가, 2=코스닥
scwin.TR_JOB;
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.rowPos;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_initForm = function(initTyp) {
    if (initTyp == "C") {
        img_ISU_CD.src = "../img/btn_search.gif";
        img_ISU_CD.setDisabled(false);
    } else if (initTyp == "X") {
        img_ISU_CD.src = "../img/btn_search_d.gif";
        img_ISU_CD.setDisabled(true);
    }
};
scwin.fn_searchCode = function() {
    /*
    01404-투자기구종류
    */
    var arrCid = [{
        cid: "INVSTORG_TP_CD",
        cnm: "cmb_INVSTORG_TP_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='INVSTORG_TP_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISU_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_ISU_KOR_NM); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.vSecugrpID;
    arrPar[3] = scwin.mktTpCd;
    arrPar[4] = SEARCH_TYP_SLC;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsuCd = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_KOR_NM.setValue(arrPar[0].ISU_NM);
        var exemBzProcsNo = arrPar[0].BZ_PROCS_NO;
        //업무처리번호대신 mktTpCd 값으로도 구분해서 사용할수 있음
        if (exemBzProcsNo == "") {
            $c.win.alert("예비심사의 업무처리번호가 없어 실행할수 없습니다.");
            buttonSet.setErrorStatus();
            scwin.fn_initForm('X');
        } else {
            //alert("[예비심사의 업무처리번호]"+exemBzProcsNo);
            $c.pre_newlisting.fn_getExem_read_sync(exemBzProcsNo);
        }
    }
};
scwin.fn_SetParInstCd = function(arrPar) {
    txb_TRST_INST_CD.setValue((arrPar.length >= 1 ? arrPar[0] : ""));
    txb_TRST_INST_NM.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
};


/**
 *사무관리
 */
scwin.fn_getParBzAdmComNm = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = dts_Item.getCellData(1, "BZ_ADM_COM_ISUR_CD"); // 코드값을 포함할 컨트롤
    arrPar[1] = txb_BZ_ADM_COM_NM.getValue(); // 명칭값을 포함할 컨트롤
    arrPar[2] = "ISUR_ALL";
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/**
 *사무관리
 */
scwin.fn_SetParBzAdmComNm = function(arrPar) {
    dts_Item.setCellData(1, "BZ_ADM_COM_ISUR_CD", arrPar[0]);
    txb_BZ_ADM_COM_NM.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
};
scwin.fn_getExem_read_sync = function(exemBzProcsNo) {
    var url = "/Newlisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=selectManagement&inputMessageId=NEWLISTING_SEARCH_OUT";
    url += "&DIV_IDX=" + DIV_R_LISTING_EXEM_BC;
    url += "&BZ_PROCS_NO=" + exemBzProcsNo;
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
};
scwin.fn_read_sync = function() {
    var url = "/Newlisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=selectManagement&inputMessageId=NEWLISTING_SEARCH_OUT";
    url += "&DIV_IDX=" + DIV_R_LISTING_BC;
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        img_ISU_CD.focus();
        return false;
    }
    if (scwin.TR_JOB == 'I') {
        if ($c.pre_newlisting.fn_checkDoubleInput(dts_DoubleChk, $c.stf.getObjectValue(txb_ISU_CD))) return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_SRT_CD) == "") {
        $c.win.alert("[종목단축코드]항목값이  없습니다.");
        txb_ISU_SRT_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_COM_NM) == "") {
        $c.win.alert("[위탁회사명]항목값이 없습니다.");
        txb_COM_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_KOR_NM) == "") {
        $c.win.alert("[한글종목명]을 입력하세요.");
        txb_ISU_KOR_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_KOR_ABBRV) == "") {
        $c.win.alert("[한글종목약명]을 입력하세요.");
        txb_ISU_KOR_ABBRV.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_ENG_NM) == "") {
        $c.win.alert("[영문종목명]을 입력하세요.");
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_ENG_ABBRV) == "") {
        $c.win.alert("[영문종목약명]을 입력하세요.");
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_TRST_INST_CD) == "") {
        $c.win.alert("[수탁회사]를 선택하세요.");
        txb_TRST_INST_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_INVSTORG_TP_CD) == "") {
        $c.win.alert("[투자기구종류]를 선택하세요.");
        cmb_INVSTORG_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_ISU_DD) == "") {
        $c.win.alert("[발행일]을 입력하세요.");
        edt_ISU_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_LIST_DD) == "") {
        $c.win.alert("[상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (scwin.vCurDate >= $c.stf.getObjectValue(edt_LIST_DD)) {
        $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_TRST_ESTB_DD) == "") {
        $c.win.alert("[신탁설정일]을 입력하세요.");
        edt_TRST_ESTB_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_TRST_END_DD) == "") {
        $c.win.alert("[신탁만료일]을 입력하세요.");
        edt_TRST_END_DD.focus();
        return false;
    }
    if (parseInt(edt_TRST_ESTB_DD.getValue(), 10) >= parseInt(edt_TRST_END_DD.getValue(), 10)) {
        $c.win.alert("[신탁설정일]은 [신탁만료일]보다 작아야 합니다. 다시 입력해주세요");
        return false;
    }
    if ($c.stf.getObjectValue(edt_TRST_ORGN_VAL) == "") {
        $c.win.alert("[신탁원본액]을 입력하세요.");
        edt_TRST_ORGN_VAL.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_TOT_STKCNT) == "") {
        $c.win.alert("[수익증권총좌수]를 입력하세요.");
        edt_TOT_STKCNT.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(edt_TOT_STKCNT, 14, "수익증권총좌수")) {
        return false;
    }
    if ($c.stf.getObjectValue(edt_PARVAL) == "") {
        $c.win.alert("[1좌당원본액]를 입력하세요.");
        edt_PARVAL.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_ISU_PRC) == "") {
        $c.win.alert("[1좌당공모발행가액]를 입력하세요.");
        edt_ISU_PRC.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_TRST_CALC_PD_CONTN) == "") {
        $c.win.alert("[신탁계산기간]을 입력하세요.");
        txb_TRST_CALC_PD_CONTN.focus();
        return false;
    }
    /*
    if (getObjectValue(txb_SALE_COM_NM) == "") {
    	alert("[판매회사]를 입력하세요.");txb_SALE_COM_NM.focus();return false;
    }

    if (getObjectValue(txb_BZ_ADM_COM_NM) == "") {
    	alert("[사무관리회사]를 입력하세요.");txb_BZ_ADM_COM_NM.focus();return false;
    }
    */

    if ($c.stf.getObjectValue(txb_ISU_BNDUNIT_NM) == "") {
        $c.win.alert("[발행권종]을 입력하세요.");
        txb_ISU_BNDUNIT_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_PROFT_DISTR_PAY_TM_CONTN) == "") {
        $c.win.alert("[이익등의분배]를 입력하세요.");
        txb_PROFT_DISTR_PAY_TM_CONTN.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txa_REMK, 2000, "비고 및 참고사항")) return false;
    return true;
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);

        //alert("[bz_procs_no]"+bz_procs_no);
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            scwin.fn_trs(TR_JOB_INSERT);
        }
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TR_JOB_UPDATE);
    }
};
scwin.fn_trs = function(trsIdx) {
    if (trsIdx == '1') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (trsIdx == '2') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (trsIdx == '3') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    dts_Item.setCellData(1, "LIST_METHD_TP_CD", LIST_METHD_TP_CD_4);
    dts_Item.setCellData(1, "ISU_RSN_CONTN", "신규상장");
    trs_Save.Action = $c.lc.fn_encodeNSession("/Newlisting.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveNewListing");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item)";
    trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",SECUGRP_ID=" + scwin.vSecugrpID + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISUR_CD=" + dts_Item.getCellData(1, "ISUR_CD") + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_103;
    trs_Save.Post();
};
scwin.fn_dscl = async function() {
    /*
    	if(  dts_Mst.IsUpdated || dts_Isu.IsUpdated || dts_Rsn.IsUpdated ) {
    		alert(getMessageParam("MSG-0022", ""));
    		return ;
    	}
    	*/
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = "68908";
        arr[1] = dts_Item.getCellData(1, "BZ_PROCS_NO");
        arr[2] = dts_Item.getCellData(1, "ISUR_CD");
        arr[3] = '1';
        arr[5] = $c.pre_newlisting.fn_getDsclsTitle($c.stf.getObjectValue(txb_ISU_KOR_NM), $c.stf.getObjectValue(edt_LIST_DD));
        $c.stf.CopyDataSet(dts_Item, param_dts_mst);
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 730 + 5;
    var hgt = 785 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
scwin.img_ISU_CD_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsuCd;
    scwin.fn_SetPar = fn_SetParIsuCd;
    $c.lc.fn_PopFindExamIsu(scwin.vSecugrpID);
};
scwin.img_TRST_INST_CD_onclick = function() {
    scwin.fn_SetPar = fn_SetParInstCd;
    $c.lc.fn_PopFindInstCd();
};
scwin.img_BZ_ADM_COM_NM_onclick = function() {
    scwin.fn_GetPar = fn_getParBzAdmComNm;
    scwin.fn_SetPar = fn_SetParBzAdmComNm;
    $c.lc.fn_PopFindIsurCdCorp();
};
scwin.img_LIST_DD_onclick = function() {
    popUpCalendar2(edt_LIST_DD);
};
scwin.img_TRST_END_DD_onclick = function() {
    popUpCalendar2(edt_TRST_END_DD);
};
scwin.img_TRST_ESTB_DD_onclick = function() {
    popUpCalendar2(edt_TRST_ESTB_DD);
};
scwin.dts_DoubleChk_OnLoadError = function() {
    $c.stf.alert_error(dts_DoubleChk);
};
scwin.dts_Item_OnLoadError = function() {
    $c.stf.alert_error(dts_Item);
};
scwin.dts_Item_OnLoadCompleted = function(rowcount) {
    if (scwin.vBzProcsNo == "") {
        buttonSet.setInsertStatus();
        scwin.fn_initForm('C');
    } else {
        scwin.fn_initForm('X');
        if ($c.stf.getObjectValue(edt_LIST_DD) > scwin.vCurDate) {
            buttonSet.setUpdateStatus();
        } else {
            buttonSet.setErrorStatus(); //disable 시킨다.

        }
    }
    //alert('[dts_Item.Status]'+dts_Item.Status);

};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_parentRefresh();
    if (buttonSet.status == "U") {
        var parentWin = $c.frame.path("../");
        parentWin.dts_List.setFocusedCell(scwin.rowPos, 0);
    }
    if (buttonSet.status == "D") {
        // 삭제처리의 응답인 경우
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_read_sync();
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Item);
    $c.elw.fn_searchCode();
    var parentWin = $c.frame.path("../");
    scwin.vBzProcsNo = parentWin.clickBzProcsNo;
    scwin.vSecugrpID = parentWin.scwin.vSecugrpID;
    scwin.mktTpCd = parentWin.scwin.mktTpCd;
    scwin.rowPos = parentWin.dts_List.getFocusedRowIndex();

    //fn_SetComboCode();

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성

    if (scwin.vBzProcsNo != "") {
        scwin.fn_read_sync();
    } else {
        dts_Item.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BENFCERT_NEWLISTING_INOUT";
        dts_Item.reset();
        dts_Item.insertRow();
    }
};
